void need(bool ok,QString why){if(!ok)throw std::runtime_error(why.toStdString());}
bool publicAddress(QHostAddress a){bool ipv4;quint32 n=a.toIPv4Address(&ipv4);if(ipv4){int x=n>>24,y=(n>>16)&255;return x>0&&x!=10&&x!=127&&x<224&&!(x==100&&y>=64&&y<=127)&&!(x==169&&y==254)&&!(x==172&&y>=16&&y<=31)&&!(x==192&&y==168)&&!(x==198&&(y==18||y==19));}return a.isGlobal();}
QString decodeHtml(QByteArray bytes,QString contentType){auto head=QString::fromLatin1(bytes.first(4096));auto m=QRegularExpression("charset\\s*=\\s*['\"]?([\\w-]+)",QRegularExpression::CaseInsensitiveOption).match(contentType+" "+head);QString charset=m.hasMatch()?m.captured(1).toLower():"utf-8";need(QStringList{"utf-8","utf8","gbk","gb2312","gb18030","us-ascii"}.contains(charset),"原文字符编码不支持");
#ifdef Q_OS_WIN
 UINT cp=charset.startsWith("utf")||charset=="us-ascii"?CP_UTF8:charset=="gb18030"?54936:936;int count=MultiByteToWideChar(cp,MB_ERR_INVALID_CHARS,bytes.constData(),int(bytes.size()),nullptr,0);need(count>0,"原文字符编码无效");std::wstring wide(count,L'\0');need(MultiByteToWideChar(cp,MB_ERR_INVALID_CHARS,bytes.constData(),int(bytes.size()),wide.data(),count)==count,"原文解码失败");return QString::fromStdWString(wide);
#else
 need(charset.startsWith("utf")||charset=="us-ascii","当前运行库未提供GBK正文解码");return QString::fromUtf8(bytes);
#endif
}
