Feed::Feed(QObject* parent,QNetworkAccessManager* manager):QObject(parent),transport(manager?manager:&owned){deadline.setSingleShot(true);deadline.setTimerType(Qt::PreciseTimer);connect(&deadline,&QTimer::timeout,this,[this]{finish("公开来源超过12秒总期限；旧缓存保留");});}
Feed::~Feed(){running=false;++generation;deadline.stop();if(lookupId>=0)QHostInfo::abortHostLookup(lookupId);if(reply){reply->disconnect(this);reply->abort();reply->deleteLater();}}
bool Feed::start(QJsonObject query){queryKey(query);if(running)return false;input=query;row={};body=false;items={};receipts={};observations={};rawResponses.clear();page=1;lid=2517;redirects=0;running=true;began=QDateTime::currentDateTimeUtc();++generation;elapsed.start();deadline.start(12000);if(query["scope"]=="announcement"){auto token=generation;QTimer::singleShot(0,this,[this,token]{if(running&&token==generation)finish("旧服务未配置独立公告源；仅读取本机公告档案，不把新闻当官方公告");});}else next();return true;}
bool Feed::readArticle(QJsonObject item){validateItem(item);if(running)return false;row=item;input={};body=true;items={};receipts={};observations={};rawResponses.clear();redirects=0;running=true;began=QDateTime::currentDateTimeUtc();++generation;elapsed.start();deadline.start(12000);try{need(!row["link"].isNull(),"资讯没有可读取原文链接");original=url(row["link"].toString(),true);currentUrl=original;request(currentUrl);}catch(const std::exception& e){finish(QString::fromUtf8(e.what()));}return true;}
void Feed::cancel(){if(!running)return;running=false;++generation;deadline.stop();if(lookupId>=0){QHostInfo::abortHostLookup(lookupId);lookupId=-1;}if(reply){auto old=reply;reply=nullptr;old->disconnect(this);old->abort();old->deleteLater();}}
void Feed::next(){if(!running)return;if(page>input["pages"].toInt()){if(lid==2517){lid=2516;page=1;}else{finish();return;}}request(QString("https://feed.mix.sina.com.cn/api/roll/get?pageid=153&lid=%1&num=50&page=%2&encode=utf-8").arg(lid).arg(page));}
void Feed::request(QString target){if(!running)return;try{need(elapsed.elapsed()<12000,"公开来源超过12秒期限");target=url(target,body);if(!body){send(target);return;}auto token=generation;lookupId=QHostInfo::lookupHost(QUrl(target).host(),this,[this,target,token](QHostInfo info){if(!running||token!=generation)return;lookupId=-1;try{need(info.error()==QHostInfo::NoError&&!info.addresses().isEmpty(),"原文DNS没有公开地址");for(auto address:info.addresses())need(publicAddress(address),"原文DNS返回私有/假IP地址，未连接或绕过");send(target,info.addresses().first().toString());}catch(const std::exception& e){finish(QString::fromUtf8(e.what()));}});}catch(const std::exception& e){finish(QString::fromUtf8(e.what()));}}
void Feed::send(QString target,QString address){if(!running)return;QUrl physical(target);auto host=physical.host();if(!address.isEmpty())physical.setHost(address);QNetworkRequest req(physical);if(body){req.setRawHeader("Host",host.toUtf8());if(physical.scheme()=="https")req.setPeerVerifyName(host);}req.setAttribute(QNetworkRequest::RedirectPolicyAttribute,QNetworkRequest::ManualRedirectPolicy);req.setAttribute(QNetworkRequest::CookieLoadControlAttribute,QNetworkRequest::Manual);req.setAttribute(QNetworkRequest::CookieSaveControlAttribute,QNetworkRequest::Manual);req.setAttribute(QNetworkRequest::AuthenticationReuseAttribute,QNetworkRequest::Manual);req.setRawHeader("Referer","https://finance.sina.com.cn/");req.setRawHeader("User-Agent","NativeMarketReview/public-news");req.setRawHeader("Accept-Encoding","identity");req.setTransferTimeout(qMax(1,12000-int(elapsed.elapsed())));auto token=generation;auto response=transport->get(req);reply=response;auto bytes=std::make_shared<QByteArray>();auto started=QDateTime::currentDateTimeUtc();connect(response,&QIODevice::readyRead,this,[this,response,token,bytes]{if(token!=generation||!running)return;auto part=response->readAll();if(bytes->size()+part.size()>2*articleMax){finish("公开来源响应超过2MiB");return;}bytes->append(part);});connect(response,&QNetworkReply::finished,this,[this,response,token,bytes,target,started]{if(token!=generation||!running){response->deleteLater();return;}bytes->append(response->readAll());int status=response->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();auto error=response->error();QString ct=response->header(QNetworkRequest::ContentTypeHeader).toString(),encoding=QString::fromLatin1(response->rawHeader("Content-Encoding")),location=QString::fromLatin1(response->rawHeader("Location"));reply=nullptr;response->disconnect(this);response->deleteLater();observations.append(QJsonObject{{"url",target},{"startedAt",time(started)},{"checkedAt",time(QDateTime::currentDateTimeUtc())},{"httpStatus",status},{"contentType",ct},{"bytes",bytes->size()},{"sha256",hash(*bytes)}});rawResponses.append(*bytes);try{need(elapsed.elapsed()<12000,"公开来源超过12秒总期限");need(bytes->size()<=2*articleMax,"公开来源响应超过2MiB");need(error==QNetworkReply::NoError||(status>=300&&status<400),QString("公开来源HTTP %1；旧缓存保留").arg(status));receive(*bytes,target,status,ct,encoding,location);}catch(const std::exception& e){finish(QString::fromUtf8(e.what()));}});}
void Feed::receive(QByteArray bytes,QString target,int status,QString ct,QString encoding,QString location){if(body&&status>=300&&status<400&&!location.isEmpty()){need(redirects++<3,"正文超过3次重定向");currentUrl=url(QUrl(target).resolved(QUrl(location)).toString(),true);request(currentUrl);return;}need(status==200,QString("公开来源HTTP %1；摘要/旧缓存保留").arg(status));need(encoding.isEmpty()||encoding.compare("identity",Qt::CaseInsensitive)==0,"来源压缩编码不支持");if(body){need(ct.startsWith("text/html",Qt::CaseInsensitive),"原文未返回HTML，PDF/商业内容通过原文入口查看");auto ps=paragraphs(decodeHtml(bytes,ct));auto a=article(row,ps,target,QDateTime::currentDateTimeUtc(),{});running=false;++generation;deadline.stop();emit articleFinished(row["id"].toString(),a,{});return;}QJsonParseError error;auto doc=QJsonDocument::fromJson(bytes,&error);need(error.error==QJsonParseError::NoError&&doc.isObject(),"新浪资讯不是有效JSON");for(auto v:sina(doc.object(),QDateTime::currentDateTimeUtc()))items.append(v);auto receipt=observations.last().toObject();receipt["lid"]=lid;receipt["page"]=page;receipts.append(receipt);++page;next();}
void Feed::finish(QString error){if(!running)return;running=false;++generation;deadline.stop();if(lookupId>=0){QHostInfo::abortHostLookup(lookupId);lookupId=-1;}if(reply){auto old=reply;reply=nullptr;old->disconnect(this);old->abort();old->deleteLater();}if(body){QJsonObject a{{"status","unavailable"},{"paragraphs",QJsonArray{}},{"sourceUrl",row["link"]},{"finalUrl",QJsonValue::Null},{"fetchedAt",time(QDateTime::currentDateTimeUtc())},{"extractor","public-article-v1"},{"origin","public-page-attempt"},{"message",error}};emit articleFinished(row["id"].toString(),a,error);}else{QJsonObject s;try{s=snapshot(input,items,receipts,began,QDateTime::currentDateTimeUtc(),error.isEmpty(),error);}catch(const std::exception& e){error=QString::fromUtf8(e.what());}emit finished(input,s,error);}}
